function needExplanation(query){return /sin (conexion|internet|anuncios|publicidad|cuenta|registro)|offline|ad.free/.test(fold(query))?'Se incluyen solo fichas que lo declaran. No es una prueba de funcionamiento.':'Busca por nombre o función, también con términos como «editar PDF» o «galería». Se usan los datos del catálogo guardado.';}
