function collectionButtons(){return '<section class="practical"><h2>Empieza por lo que necesitas</h2><div class="practical-grid">'+practicalCollections.map(([id,title,icon])=>'<button data-collection="'+id+'"><i data-lucide="'+icon+'"></i><span>'+title+'</span><i data-lucide="chevron-right"></i></button>').join('')+'</div></section>';}
