function plainFacts(a){const f=declaredFacts(a),asset=recommended(a);return '<section class="plain-facts"><h2>Lo esencial</h2><dl class="facts"><div><dt>Uso sin conexión</dt><dd>'+f.offline+'</dd></div><div><dt>Cuenta obligatoria</dt><dd>'+f.account+'</dd></div><div><dt>Anuncios</dt><dd>'+f.ads+'</dd></div><div><dt>Descarga sugerida</dt><dd>'+(asset&&asset.size>0?size(asset.size):'Por comprobar')+'</dd></div></dl><p class="source-caption">'+(a.source==='fdroid'?'Según la descripción y los avisos de F-Droid.':'Según la descripción de esta ficha. Los datos de otra versión no se trasladan automáticamente.')+' Sin prueba funcional de Kivo.</p><details><summary>Privacidad y permisos</summary><p class="about">Seguimiento: '+f.tracking+'. Los permisos se muestran en Android cuando corresponde. Esta ficha no incluye todavía una comparación de permisos entre versiones.</p></details></section>';}

