function popularity(a){return (!a.source||a.source==='github')?Number(a.stars)||0:packageStars.get(a.package)||0;}
function stamp(value){const n=typeof value==='number'?value:Date.parse(value||'');return Number.isFinite(n)&&n>0?n:0;}
function newProjects(list){return list.filter(a=>a.source!=='aurora'&&stamp(a.createdAt||a.addedAt)).sort((a,b)=>stamp(b.createdAt||b.addedAt)-stamp(a.createdAt||a.addedAt));}
