function openImage(app,index,opener){if(!(app.screenshots||[]).length)return;if(device.nativeGallery){call('showScreenshots',app.repo,index);return;}viewerApp=app;viewerIndex=Math.max(0,Math.min(index,app.screenshots.length-1));viewerOpener=opener;document.body.style.overflow='hidden';const dialog=q('#image-dialog');if(!dialog.open){if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');}drawImage();q('[data-close-image]').focus();}
function drawImage(){if(!viewerApp)return;const shots=viewerApp.screenshots||[];q('#viewer-title').textContent=viewerApp.name;q('#viewer-counter').textContent=(viewerIndex+1)+' / '+shots.length;q('[data-prev-image]').disabled=viewerIndex===0;q('[data-next-image]').disabled=viewerIndex===shots.length-1;q('#viewer-state').textContent='Cargando captura…';q('[data-retry-image]').hidden=true;q('#image-preview').alt='Captura '+(viewerIndex+1)+' de '+viewerApp.name;q('#image-preview').src='https://kivo.local/media?repo='+encodeURIComponent(viewerApp.repo)+'&i='+viewerIndex;}
